-- KLOVR Precision — the whole database, in order.
--
-- Generated by scripts/build-schema.js from supabase/migrations/. Do not edit
-- this file; edit the migration and regenerate, or CI will notice.
--
-- Paste the lot into the Supabase SQL editor and run it once, on a new project.
--
-- It is wrapped in a transaction, so if anything fails nothing is applied and
-- you can fix it and paste again. That also means running it a second time on a
-- database that already has these tables stops at the first CREATE TYPE and
-- rolls the whole thing back, rather than half-applying anything. To change
-- something later, write a new migration rather than re-running this.
--
-- 10 migrations, in this order:
--    1. 0001_schema.sql
--    2. 0002_rls.sql
--    3. 0003_seed.sql
--    4. 0004_create_order.sql
--    5. 0005_storefront_fields.sql
--    6. 0006_catalogue_content.sql
--    7. 0007_ffl_directory.sql
--    8. 0008_site_events.sql
--    9. 0009_order_notices.sql
--   10. 0010_product_editor.sql

begin;

-- ==========================================================================
-- 0001_schema.sql
-- ==========================================================================

-- KLOVR Precision — staff/admin schema
-- Money is stored in integer cents. Never floats.

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------- enums
create type delivery_rule as enum ('door','ffl','nfa');
create type order_status  as enum ('new','paid','hold','at_dealer','shipped','complete','cancelled');
create type destination   as enum ('door','ffl');

-- ---------------------------------------------------------------- staff
-- One row per employee, keyed to the Supabase auth user. Membership of this
-- table is what "is an employee" means; there is no self-signup.
create table public.staff (
  id          uuid primary key references auth.users on delete cascade,
  email       text not null,
  full_name   text,
  role        text not null default 'staff' check (role in ('staff','manager','owner')),
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------- catalogue
create table public.products (
  id              uuid primary key default gen_random_uuid(),
  sku             text unique not null,
  name            text not null,
  category        text,
  description     text[]  not null default '{}',
  specs           jsonb   not null default '[]',
  images          text[]  not null default '{}',
  price_cents     integer not null check (price_cents >= 0),
  stock           integer not null default 0 check (stock >= 0),
  built_to_order  boolean not null default false,
  -- how this item is allowed to reach a buyer. Drives checkout, not just labels.
  delivery        delivery_rule not null default 'door',
  -- states we may not send it to at all, e.g. ammunition to CA
  no_ship_states  text[] not null default '{}',
  note            text,
  is_live         boolean not null default false,
  qb_item_id      text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index products_live_idx on public.products (is_live) where is_live;
create index products_category_idx on public.products (category);

-- ---------------------------------------------------------------- dealers
create table public.ffl_dealers (
  id                 uuid primary key default gen_random_uuid(),
  licence            text unique not null,
  business_name      text not null,
  address1           text,
  city               text,
  state              char(2),
  zip                text,
  phone              text,
  transfer_fee_cents integer,
  -- set when the licence was last confirmed current against ATF eZ Check
  verified_at        timestamptz,
  created_at         timestamptz not null default now()
);
create index ffl_dealers_zip_idx on public.ffl_dealers (zip);

-- ---------------------------------------------------------------- orders
create sequence if not exists order_ref_seq start 1059;

create table public.orders (
  id              uuid primary key default gen_random_uuid(),
  reference       text unique not null default 'KP-' || nextval('order_ref_seq'),
  placed_at       timestamptz not null default now(),
  customer_name   text not null,
  customer_email  text not null,
  customer_phone  text,
  destination     destination not null,
  ship_address    jsonb,                 -- used when destination = 'door'
  ffl_dealer_id   uuid references public.ffl_dealers,
  status          order_status not null default 'new',
  subtotal_cents  integer not null default 0,
  carrier         text,
  tracking        text,
  note            text,
  qb_invoice_id   text,
  qb_invoice_no   text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  -- a firearm order must name the dealer it is going to. Enforced here so no
  -- application bug can create one without a destination dealer.
  constraint ffl_orders_need_a_dealer
    check (destination <> 'ffl' or ffl_dealer_id is not null),
  constraint door_orders_need_an_address
    check (destination <> 'door' or ship_address is not null)
);
create index orders_status_idx on public.orders (status);
create index orders_placed_idx on public.orders (placed_at desc);

create table public.order_lines (
  id               uuid primary key default gen_random_uuid(),
  order_id         uuid not null references public.orders on delete cascade,
  product_id       uuid references public.products on delete set null,
  sku              text not null,
  name             text not null,
  qty              integer not null check (qty > 0),
  unit_price_cents integer not null check (unit_price_cents >= 0)
);
create index order_lines_order_idx on public.order_lines (order_id);

-- ---------------------------------------------------------------- quickbooks
-- Single row. OAuth refresh tokens live here and must never leave the server;
-- see 0002_rls.sql — this table gets RLS on and no policies at all, so only the
-- service_role key (server-side) can read it.
create table public.qb_connection (
  id            boolean primary key default true check (id),
  realm_id      text,
  access_token  text,
  refresh_token text,
  expires_at    timestamptz,
  connected_at  timestamptz,
  last_sync_at  timestamptz
);

create table public.qb_sync_log (
  id      bigserial primary key,
  at      timestamptz not null default now(),
  level   text not null default 'info' check (level in ('info','warn','error')),
  message text not null
);
create index qb_sync_log_at_idx on public.qb_sync_log (at desc);

-- ---------------------------------------------------------------- updated_at
create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;

create trigger products_touch before update on public.products
  for each row execute function public.touch_updated_at();
create trigger orders_touch before update on public.orders
  for each row execute function public.touch_updated_at();

-- ==========================================================================
-- 0002_rls.sql
-- ==========================================================================

-- Row level security.
-- Default posture: deny. Every table below has RLS on, so anything without a
-- matching policy is invisible — including to a leaked anon key.

-- Membership of public.staff is the definition of "is an employee".
-- security definer so the policy can read the table without recursing into its
-- own RLS; search_path pinned so it cannot be shadowed.
create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.staff where id = auth.uid())
$$;
revoke execute on function public.is_staff() from anon;
grant  execute on function public.is_staff() to authenticated;

alter table public.staff         enable row level security;
alter table public.products      enable row level security;
alter table public.ffl_dealers   enable row level security;
alter table public.orders        enable row level security;
alter table public.order_lines   enable row level security;
alter table public.qb_connection enable row level security;
alter table public.qb_sync_log   enable row level security;

-- ---------------------------------------------------------------- staff
-- An employee may see their own row and nobody else's. Adding employees is done
-- from the Supabase dashboard, or by the service_role key. There is no signup.
create policy staff_read_self on public.staff
  for select to authenticated using (id = auth.uid());

-- ---------------------------------------------------------------- products
-- The storefront reads live products with the anon key. That is the only thing
-- the anon key can see anywhere in this database.
create policy products_public_read on public.products
  for select to anon, authenticated using (is_live);

create policy products_staff_read on public.products
  for select to authenticated using (public.is_staff());
create policy products_staff_write on public.products
  for all to authenticated using (public.is_staff()) with check (public.is_staff());

-- ---------------------------------------------------------------- dealers
-- Dealer records include licence numbers. Staff only.
create policy dealers_staff_all on public.ffl_dealers
  for all to authenticated using (public.is_staff()) with check (public.is_staff());

-- ---------------------------------------------------------------- orders
-- Customer names, addresses, and the dealer they are transferring through.
-- Staff only, with no public read of any kind.
--
-- Note there is deliberately no INSERT policy for anon. Orders are created
-- server-side by a Netlify Function using the service_role key, so a browser
-- cannot forge prices or bypass the destination rules.
create policy orders_staff_all on public.orders
  for all to authenticated using (public.is_staff()) with check (public.is_staff());
create policy order_lines_staff_all on public.order_lines
  for all to authenticated using (public.is_staff()) with check (public.is_staff());

-- ---------------------------------------------------------------- quickbooks
-- qb_connection holds OAuth access and refresh tokens.
-- RLS is ON and there are NO policies, by design: neither the anon key nor a
-- signed-in employee can read it from a browser. Only the service_role key,
-- which bypasses RLS and never leaves the server, can touch this table.

-- The log has no secrets, so staff may read it.
create policy qb_log_staff_read on public.qb_sync_log
  for select to authenticated using (public.is_staff());

