-- ==========================================================================
-- 0007_ffl_directory.sql
-- ==========================================================================

-- FFL directory.
--
-- Source is the ATF listing of active Federal Firearms Licensees, which ATF
-- publishes monthly and makes available to licence holders through eZ Check.
-- It excludes type 03 collectors and type 06 ammunition manufacturers.
--
-- There is no API for eZ Check — ATF has said so. Verifying that one licence is
-- currently valid is therefore a manual lookup a member of staff performs, and
-- verified_at records when they did it. Nothing here scrapes ATF.

alter table public.ffl_dealers add column if not exists licence_name text;
alter table public.ffl_dealers add column if not exists licence_type char(2);
alter table public.ffl_dealers add column if not exists expires_on   date;
alter table public.ffl_dealers add column if not exists source       text;
alter table public.ffl_dealers add column if not exists imported_at  timestamptz;
alter table public.ffl_dealers add column if not exists verified_by  text;

-- Which licence types may actually receive a firearm transfer.
-- 01 dealer · 02 pawnbroker · 07 manufacturer · 08 importer
-- 09/10/11 destructive devices. Deliberately excludes 03 (collector, curio and
-- relic only) and 06 (ammunition manufacturer) — neither can take a transfer.
alter table public.ffl_dealers
  add column if not exists can_transfer boolean
  generated always as (licence_type in ('01','02','07','08','09','10','11')) stored;

create index if not exists ffl_zip_idx    on public.ffl_dealers (zip);
create index if not exists ffl_zip3_idx   on public.ffl_dealers (left(zip, 3));
create index if not exists ffl_state_idx  on public.ffl_dealers (state);

-- ---------------------------------------------------------------- search
-- Public: the checkout needs this before anyone has signed in. security definer
-- so it can read a staff-only table, returning only the columns a customer
-- needs — never the whole row.
--
-- Proximity without geocoding: an exact ZIP beats a shared 4-digit prefix,
-- which beats a shared 3-digit prefix (the same sectional centre), which beats
-- merely being in the same state. Good enough to put the right dealer first.
create or replace function public.find_ffls(p_zip text, p_state text default null, p_limit int default 12)
returns table (
  licence       text,
  business_name text,
  address1      text,
  city          text,
  state         char(2),
  zip           text,
  phone         text,
  expires_on    date,
  proximity     int
)
language sql
stable
security definer
set search_path = public
as $$
  select d.licence, coalesce(d.business_name, d.licence_name) as business_name,
         d.address1, d.city, d.state, d.zip, d.phone, d.expires_on,
         case when d.zip = p_zip                              then 0
              when left(d.zip,4) = left(p_zip,4)              then 1
              when left(d.zip,3) = left(p_zip,3)              then 2
              else 3 end as proximity
  from public.ffl_dealers d
  where d.can_transfer
    and (d.expires_on is null or d.expires_on >= current_date)
    and ( left(d.zip,3) = left(p_zip,3)
          or (p_state is not null and d.state = upper(p_state)) )
  order by proximity, coalesce(d.business_name, d.licence_name)
  limit least(greatest(p_limit,1), 25)
$$;

grant execute on function public.find_ffls(text, text, int) to anon, authenticated;

-- Staff record a manual eZ Check the moment they do one.
create or replace function public.mark_ffl_verified(p_licence text, p_by text)
returns void language sql security definer set search_path = public as $$
  update public.ffl_dealers
     set verified_at = now(), verified_by = p_by
   where licence = p_licence
$$;
revoke execute on function public.mark_ffl_verified(text, text) from public, anon;
grant  execute on function public.mark_ffl_verified(text, text) to authenticated;

-- ==========================================================================
-- 0008_site_events.sql
-- ==========================================================================

-- Site events.
--
-- First-party, on purpose. The privacy page tells customers this site runs no
-- third-party trackers, and firearms customers have a particular reason to care
-- who holds a list with their name on it. Keeping the measurement here means
-- that sentence stays true, and it costs nothing.
--
-- What is deliberately NOT here: no cookie, no durable visitor id, no IP
-- address, no user agent string, no full referrer, no city, and no link of any
-- kind between an event and an order or a customer. The session column is a
-- random value the browser keeps in sessionStorage — it dies with the tab, and
-- its only job is to let a funnel count one person once.

create table if not exists public.site_events (
  id        bigserial primary key,
  at        timestamptz not null default now(),
  -- ephemeral, per browser tab; not a visitor id and never joined to anything
  session   text not null,
  name      text not null,
  props     jsonb not null default '{}'::jsonb,
  path      text,
  -- host only. "duckduckgo.com", never the URL somebody arrived from.
  ref_host  text,
  -- country and state. A shop that cannot ship certain items to certain states
  -- has a real use for this; the city would be precision nobody asked for.
  country   text,
  region    text,
  device    text check (device in ('mobile','desktop'))
);

create index if not exists site_events_at_idx    on public.site_events (at desc);
create index if not exists site_events_name_idx  on public.site_events (name, at desc);
create index if not exists site_events_props_idx on public.site_events using gin (props);

-- Deny by default, like everything else. There is no insert policy at all:
-- writes arrive through netlify/functions/collect.js with the service key,
-- which is the only place event names are validated.
alter table public.site_events enable row level security;

drop policy if exists site_events_staff_read on public.site_events;
create policy site_events_staff_read on public.site_events
  for select to authenticated using (is_staff());

-- ---------------------------------------------------------------- reporting
-- security definer so one is_staff() check gates the lot, search_path pinned so
-- these cannot be shadowed.

-- What happened, and how much of it.
create or replace function public.events_summary(p_days int default 30)
returns table (name text, events bigint, sessions bigint)
language sql stable security definer set search_path = public as $$
  select e.name, count(*), count(distinct e.session)
  from site_events e
  where is_staff() and e.at > now() - make_interval(days => greatest(p_days, 1))
  group by e.name
  order by 2 desc
$$;

-- Searches that found nothing. For a shop this is the most directly actionable
-- thing on the page: it is a list of what people came for and did not get.
create or replace function public.search_gaps(p_days int default 30)
returns table (q text, times bigint, last_at timestamptz)
language sql stable security definer set search_path = public as $$
  select lower(e.props->>'q'), count(*), max(e.at)
  from site_events e
  where is_staff()
    and e.name = 'search'
    and coalesce((e.props->>'n')::int, 0) = 0
    and coalesce(e.props->>'q', '') <> ''
    and e.at > now() - make_interval(days => greatest(p_days, 1))
  group by 1
  order by 2 desc, 3 desc
$$;

-- What people actually spec when they build a rifle. This is stock intelligence
-- that cannot be got any other way — a chambering nobody picks is barrel money
-- sitting on a shelf.
create or replace function public.build_choices(p_days int default 30)
returns table (step text, choice text, picks bigint, sessions bigint)
language sql stable security definer set search_path = public as $$
  select e.props->>'k', e.props->>'v', count(*), count(distinct e.session)
  from site_events e
  where is_staff()
    and e.name = 'build_step'
    and coalesce(e.props->>'k', '') <> ''
    and e.at > now() - make_interval(days => greatest(p_days, 1))
  group by 1, 2
  order by 1, 3 desc
$$;

-- Where checkout loses people. Counted by session so one person hitting Back
-- does not read as two.
create or replace function public.checkout_funnel(p_days int default 30)
returns table (step int, sessions bigint)
language sql stable security definer set search_path = public as $$
  select (e.props->>'step')::int, count(distinct e.session)
  from site_events e
  where is_staff()
    and e.name = 'checkout_step'
    and (e.props->>'step') ~ '^[1-4]$'
    and e.at > now() - make_interval(days => greatest(p_days, 1))
  group by 1
  order by 1
$$;

-- Looked at versus put in a basket, per product.
create or replace function public.product_interest(p_days int default 30)
returns table (sku text, views bigint, carted bigint)
language sql stable security definer set search_path = public as $$
  select coalesce(v.sku, c.sku), coalesce(v.n, 0), coalesce(c.n, 0)
  from (select props->>'sku' as sku, count(*) n from site_events
        where name = 'product_view' and at > now() - make_interval(days => greatest(p_days, 1))
        group by 1) v
  full join
       (select props->>'sku' as sku, count(*) n from site_events
        where name = 'add_to_cart' and at > now() - make_interval(days => greatest(p_days, 1))
        group by 1) c on c.sku = v.sku
  where is_staff()
  order by 2 desc nulls last
$$;

revoke execute on function public.events_summary(int)   from anon;
revoke execute on function public.search_gaps(int)      from anon;
revoke execute on function public.build_choices(int)    from anon;
revoke execute on function public.checkout_funnel(int)  from anon;
revoke execute on function public.product_interest(int) from anon;

-- Nothing here is worth keeping for years. Run this on a schedule (Supabase
-- dashboard → Database → Cron) or call it by hand now and then.
create or replace function public.prune_site_events(p_keep_days int default 400)
returns bigint
language plpgsql security definer set search_path = public as $$
declare n bigint;
begin
  delete from site_events where at < now() - make_interval(days => greatest(p_keep_days, 30));
  get diagnostics n = row_count;
  return n;
end $$;
revoke execute on function public.prune_site_events(int) from anon, authenticated;

-- ==========================================================================
-- 0009_order_notices.sql
-- ==========================================================================

-- Whether anybody was told the order arrived.
--
-- An order sitting in a table nobody opened is the same as no order. Email is
-- sent after the order is committed, so it can fail on its own — and when it
-- does, the row has to say so, or the failure is invisible and the customer is
-- waiting on a reply that was never sent.

alter table public.orders
  add column if not exists notified_at    timestamptz,
  add column if not exists notify_error   text;

comment on column public.orders.notified_at is
  'When the shop and the customer were emailed about this order. Null means nobody has been told.';
comment on column public.orders.notify_error is
  'Why the email did not go out, if it did not. Shown in /admin so it cannot pass unnoticed.';

-- Orders nobody has been told about, oldest first. The one query worth having
-- as a view: if this returns rows, somebody is waiting.
create or replace view public.unnotified_orders
  with (security_invoker = on) as
  select reference, placed_at, customer_name, customer_email, status, notify_error
  from public.orders
  where notified_at is null
  order by placed_at;

-- The function marks its own work. Only service_role reaches this.
create or replace function public.mark_order_notified(p_reference text, p_error text default null)
returns void
language sql
security definer
set search_path = public
as $$
  update public.orders
     set notified_at = case when p_error is null then now() else notified_at end,
         notify_error = p_error,
         updated_at = now()
   where reference = p_reference
$$;
revoke execute on function public.mark_order_notified(text, text) from anon, authenticated;

-- ==========================================================================
-- 0010_product_editor.sql
-- ==========================================================================

-- What the full product editor needs that the schema did not already have.
--
-- Almost nothing, as it turns out: description, specs, images, no_ship_states,
-- summary, filter_key and sort_order were all there from 0001 and 0005. Only
-- two things were missing — a label for how a built-to-order item is described,
-- and somewhere to put a photograph.

-- "Built to order" is right for a rifle we machine and wrong for a bipod we
-- order in from a distributor. Both are the same flag; only the wording differs.
alter table public.products
  add column if not exists made_label text;

comment on column public.products.made_label is
  'How built_to_order reads on the storefront: "Built to order", "Ordered in". Null falls back to the default wording.';

-- ---------------------------------------------------------------- photographs
-- Product photos live in Supabase Storage rather than the repository, because
-- the whole point of this editor is that adding a product does not require a
-- commit. The trade: photos in site/web/ are committed with an AVIF rendition
-- beside them, and these are not — there is no AVIF encoder on a Linux build
-- box. They are served as uploaded. build.js says how many, on every build.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('product-photos', 'product-photos', true, 10485760,
        array['image/jpeg','image/png','image/webp','image/avif'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Anyone may look at a product photo — they are on a public shop page. Only
-- staff may put one there or take one away.
drop policy if exists product_photos_public_read on storage.objects;
create policy product_photos_public_read on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'product-photos');

drop policy if exists product_photos_staff_write on storage.objects;
create policy product_photos_staff_write on storage.objects
  for insert to authenticated
  with check (bucket_id = 'product-photos' and public.is_staff());

drop policy if exists product_photos_staff_update on storage.objects;
create policy product_photos_staff_update on storage.objects
  for update to authenticated
  using (bucket_id = 'product-photos' and public.is_staff());

drop policy if exists product_photos_staff_delete on storage.objects;
create policy product_photos_staff_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'product-photos' and public.is_staff());

-- ---------------------------------------------------------------- guard rails
-- The editor is a form, and a form can be filled in wrongly. These are the
-- mistakes that would reach a customer as a broken page or, worse, as a firearm
-- routed somewhere it may not go.

-- Two-letter state codes, uppercase. 'Ca' or 'Calif' would silently never match
-- the destination and the item would ship somewhere it must not.
alter table public.products drop constraint if exists products_no_ship_states_are_codes;
alter table public.products add constraint products_no_ship_states_are_codes
  check (no_ship_states <@ array[
    'AL','AK','AZ','AR','CA','CO','CT','DE','DC','FL','GA','HI','ID','IL','IN','IA','KS','KY','LA',
    'ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH','OK','OR',
    'PA','RI','SC','SD','TN','TX','UT','VT','VA','WA','WV','WI','WY','PR','VI','GU','AS','MP']::text[]);

-- specs is [["Label","Value"], …]. Anything else and the product page renders
-- empty cells rather than a table.
--
-- The obvious way to write this is a NOT EXISTS over jsonb_array_elements, and
-- it parses — but Postgres refuses a subquery inside a CHECK constraint at
-- execution time. An immutable function holds the same test and is allowed.
create or replace function public.specs_are_pairs(p jsonb)
returns boolean
language sql
immutable
as $$
  select jsonb_typeof(p) = 'array'
     and not exists (
       select 1 from jsonb_array_elements(p) e
       where jsonb_typeof(e) <> 'array'
          or jsonb_array_length(e) <> 2
          or jsonb_typeof(e->0) <> 'string'
          or jsonb_typeof(e->1) <> 'string'
     )
$$;

alter table public.products drop constraint if exists products_specs_are_pairs;
alter table public.products add constraint products_specs_are_pairs
  check (public.specs_are_pairs(specs));

-- A live product with no name, no price or no SKU is a broken card in the shop.
alter table public.products drop constraint if exists products_live_ones_are_complete;
alter table public.products add constraint products_live_ones_are_complete
  check (not is_live or (length(trim(name)) > 0 and length(trim(sku)) > 0));

commit;
